function worldPoint(canvas,event,art){const q=canvasPoint(canvas,event),meta=art.tiles,scale=Math.min(canvas.width/meta.width,canvas.height/meta.height)*mapView.zoom,ox=(canvas.width-meta.width*scale)/2+mapView.panX,oy=(canvas.height-meta.height*scale)/2+mapView.panY;return{x:(q.x-ox)/scale,y:(q.y-oy)/scale}}
function attachMapInput(){document.addEventListener("wheel",event=>{if(!event.target.closest(".map-canvas"))return;event.preventDefault();const canvas=event.target,art=latest?.journey?.map_art;if(!art?.tiles)return;const p=canvasPoint(canvas,event),before=worldPoint(canvas,event,art),old=mapView.zoom;mapView.zoom=Math.max(.5,Math.min(32,old*(event.deltaY<0?1.2:1/1.2)));const base=Math.min(canvas.width/art.tiles.width,canvas.height/art.tiles.height),newScale=base*mapView.zoom;mapView.panX=p.x-(canvas.width-art.tiles.width*newScale)/2-before.x*newScale;mapView.panY=p.y-(canvas.height-art.tiles.height*newScale)/2-before.y*newScale;drawArtMap(canvas,art,latest.journey,calibrationRun())},{passive:false});document.addEventListener("pointerdown",event=>{if(event.target.id==="map-canvas")event.target.setPointerCapture(event.pointerId),event.target._drag={x:event.clientX,y:event.clientY,px:mapView.panX,py:mapView.panY,moved:false}});document.addEventListener("pointermove",event=>{const c=event.target;if(c.id!=="map-canvas"||!c._drag)return;const dx=event.clientX-c._drag.x,dy=event.clientY-c._drag.y;if(Math.hypot(dx,dy)>4)c._drag.moved=true;const r=c.getBoundingClientRect();mapView.panX=c._drag.px+dx*c.width/r.width;mapView.panY=c._drag.py+dy*c.height/r.height;drawArtMap(c,latest?.journey?.map_art,latest?.journey,calibrationRun())});document.addEventListener("pointerup",event=>{if(event.target.id==="map-canvas"){event.target._lastDrag=Boolean(event.target._drag?.moved);event.target._drag=null}});document.addEventListener("click",event=>{const canvas=event.target;if(canvas.id!=="map-canvas"||mapView.activeAnchor<0)return;if(canvas._lastDrag){canvas._lastDrag=false;return}const art=latest?.journey?.map_art;if(!art?.tiles)return;const point=worldPoint(canvas,event,art),index=mapView.activeAnchor;mapView.anchors[index]=point;mapView.activeAnchor=-1;renderWizardPointList();drawArtMap(canvas,art,latest.journey,calibrationRun())})}

function simpleState(snapshot){const status=snapshot.status||{},active=status.active_launches||[];if(stopping&&active.length===0&&snapshot.last_completion?.safe)return "Parado com segurança ✓";if(active.some(a=>a.status==="STOP_REQUESTED"))return "Parando com segurança…";if(active.some(a=>a.status==="FAILED"||a.status==="PROBLEM"))return "Precisa de atenção";return active.length?"Treino rodando":"Parado"}
function setStatusBanner(kind,message,detail=null,warnings=[],events=[]){const root=$("status-banner");root.className=`status-banner ${["running","warning","error"].includes(kind)?kind:"idle"}`;$("status-message").textContent=message;const list=$("status-alert-list");const shown=kind==="warning"?warnings.slice(0,8):[];list.hidden=!shown.length;list.innerHTML=shown.map(item=>`<span>${esc(item)}</span>`).join("");const details=$("status-technical");details.hidden=!detail;$("status-technical-detail").textContent=detail||"";const eventBox=$("status-events");eventBox.hidden=!events.length;$("status-event-list").innerHTML=events.slice(0,8).map(item=>`<div class="status-event"><strong>${esc(item.status||"evento")} · ${esc(item.role||"treino")}</strong><span>${esc(item.message||"")}</span>${item.technical_detail?`<details><summary>Detalhes técnicos</summary><pre>${esc(item.technical_detail)}</pre></details>`:""}</div>`).join("")}
function friendlyFailure(reason){const raw=String(reason||"erro não informado"),s=raw.toLowerCase();if(s.includes("warm-start campaigns must use a new shared checkpoint directory"))return "A pasta de checkpoints já está em uso; continue a campanha existente ou use outra pasta.";if(/bridge disconnected|bridge desconectou|connection reset|broken pipe/.test(s))return "A conexão com a ponte do jogo foi interrompida.";if(/relaunch limit|maximum relaunch|limite de relançamentos/.test(s))return "A instância atingiu o limite de relançamentos automáticos.";if(/no shared-learner checkpoint|no checkpoint|checkpoint is unavailable/.test(s))return "Não há checkpoint disponível para continuar o treino.";if(/personal game|jogo pessoal|another hollow knight process|game already open/.test(s))return "O Hollow Knight pessoal parece estar aberto; feche-o antes de iniciar o treino.";return "O treino parou após uma falha. Consulte os detalhes técnicos."}
function renderInstances(rows){const labels={STARTING:"iniciando",RUNNING:"jogando",RESTARTING:"reiniciando",EVALUATING:"Avaliando (prova rápida)",FAILED:"com problema",PROBLEM:"com problema",CANCELLED:"cancelada",COMPLETED:"concluída",STOP_REQUESTED:"parando com segurança",unknown:"aguardando"};const root=$("instance-list");root.innerHTML=rows.length?rows.map((row,index)=>{const status=String(row.status||"unknown"),problem=row.problem===true||status==="FAILED"||status==="PROBLEM"||status==="CANCELLED",activity=row.activity_label||labels[status]||status,steps=Number(row.evaluation_steps);return `<span class="instance-pill ${problem?"problem":""}">Instância ${esc(row.slot??index+1)} · ${esc(activity)}${status==="EVALUATING"&&Number.isFinite(steps)?` · ${steps}/1000 passos`:""}${row.reason?` — ${esc(row.reason)}`:""}${row.restarts_last_hour?` · ${esc(row.restarts_last_hour)} reinícios/h`:""}</span>`}).join(""):'<span class="instance-pill">Nenhuma instância ativa</span>'}
function renderEvaluations(rows){const root=$("evaluation-chart"),recent=Array.isArray(rows)?rows.slice(-12).reverse():[];root.innerHTML=recent.length?`<div class="table-scroll"><table class="bestiary-table"><thead><tr><th>Rodada</th><th>Prova</th><th>Retorno</th><th>Progresso máximo</th><th>Tempo até travar</th><th>Passos</th></tr></thead><tbody>${recent.map(row=>`<tr><th>R${esc(row.round)} · ator ${esc(Number(row.slot)+1)}</th><td><span class="evaluation-seal">PROVA · ${row.measure==="stochastic"?"estocástica":"determinística"}</span></td><td>${fixed(row.return,2)}</td><td>${fixed(row.evaluation_max_progress,1)} u</td><td>${row.time_until_stuck_seconds==null?"—":`${fixed(row.time_until_stuck_seconds,1)} s`}</td><td>${esc(row.steps)}</td></tr>`).join("")}</tbody></table></div>`:'<p class="empty">A primeira avaliação aparece após as primeiras rodadas.</p>'}
function renderPlaythroughs(rows){const root=$("playthrough-list");root.innerHTML=rows.length?rows.map(row=>{const progress=row.progress||{},scene=row.last_scene||"Aguardando primeira cena",checkpoint=progress.checkpoint?` · banco ${progress.checkpoint}`:"",step=Number(progress.step)||0,disabled=row.can_manage!==true;return `<article class="playthrough-row"><div><strong>Instância ${esc(row.slot)} · ${esc(friendlyScene(scene))}</strong><small>${step?`${step} passos recentes`:"Progresso ainda não registrado"} · ${Number(row.backup_count)||0} backups${esc(checkpoint)}</small></div><div class="button-row"><button class="button secondary" data-playthrough-action="new" data-slot="${esc(row.slot)}" ${disabled?"disabled":""}>Começar jogada nova</button><button class="button secondary" data-playthrough-action="restore" data-slot="${esc(row.slot)}" ${disabled||!(Number(row.backup_count)>0)?"disabled":""}>Restaurar último backup bom</button></div></article>`}).join(""):'<p class="empty">A campanha selecionada não usa jogada contínua.</p>'}
function render(data){latest=data;latestError=null;const status=data.status||{},active=status.active_launches||[],running=active.length>0;const banner=data.status_banner||{kind:running?"running":"idle",message:running?`Treinando — rodada ${data.learner_updates||0}, ${fixed(data.steps_per_second,1)} passos/s`:"Treino parado — aguardando início."};setStatusBanner(banner.kind,banner.message,banner.technical_detail,data.alerts||[],data.recent_events||[]);const state=simpleState(data);$("run-status").textContent=state;$("run-status").className="status-badge "+(running?(stopping?"stopping":"running"):(state.includes("atenção")?"problem":""));$("live-label").textContent="Painel local conectado";$("live-dot").className="dot online";$("elapsed").textContent=duration(data.elapsed_seconds);$("remaining").textContent=data.remaining_seconds===null?"Sem limite":duration(data.remaining_seconds);$("instance-status").textContent=`${active.filter(a=>a.role==="actor").length} jogando / ${active.length?"1 cérebro da IA":"0 ativas"}`;$("cpu").textContent=data.system?.cpu_percent===null?"—":`${data.system?.cpu_percent??"—"}%`;const mb=data.system?.memory_used_bytes,total=data.system?.memory_total_bytes;$("memory").textContent=Number.isFinite(mb)&&Number.isFinite(total)?`${(mb/1073741824).toFixed(1).replace(".",",")} / ${(total/1073741824).toFixed(1).replace(".",",")} GB`:"—";$("speed").textContent=fixed(data.steps_per_second,1);$("updates").textContent=fixed(data.updates_per_hour,1);
renderActorPerformance(data.actor_performance||[]);renderInstances(data.instances||[]);renderPlaythroughs(data.playthroughs||[]);renderBestiary(data.playthroughs||[]);renderChallenges(data.playthroughs||[],data.help_requests_enabled===true,data.challenge_practice_enabled===true);const recent=(data.episode_progress||[]).filter(row=>row.evaluation_only!==true);const last=recent.at(-1);$("rooms-episode").textContent=last?.distinct_scenes??"—";$("rooms-total").textContent=(data.scenes_discovered||[]).length;$("deaths-hour").textContent=fixed(data.deaths_per_hour,1);$("shade-hour").textContent=fixed(data.shade_recoveries_per_hour,1);$("first-room-time").textContent=data.average_steps_to_first_scene===null?"—":`${fixed(data.average_steps_to_first_scene,0)} passos`;$("max-room-progress").textContent=data.max_room_progress?.scene?`${esc(data.max_room_progress.scene)} · ${fixed(data.max_room_progress.distance,1)} u`:"—";
chart("scene-chart",data.scene_trend||[],"episode","distinct_scenes");renderEvaluations(data.evaluations||[]);renderScenes(data.scenes_discovered||[]);renderJourney(data.journey);renderMapArt(data.journey);const alerts=data.alerts||[];$("alerts").innerHTML=alerts.length?alerts.map(item=>`<div class="alert ${String(item).startsWith("learner caiu:")?"critical":""}">${esc(item)}</div>`).join(""):'<p class="empty">Nenhum alerta. O treino segue normalmente.</p>';renderReports(data.reports||[]);
const max=Math.max(1,Number(data.max_instances)||1),select=$("instance-count"),old=Number(select.value)||1;select.innerHTML=Array.from({length:max},(_,i)=>`<option value="${i+1}">${i+1} ${i===0?"instância":"instâncias"}</option>`).join("");select.value=String(Math.min(old,max));select.disabled=running;$("recommendation").textContent=`Recomendação para esta máquina: ${data.recommended_instances||1} instância(s).`;
$("start-training").disabled=running;$("continue-training").disabled=running||!data.can_continue;$("repeat-training").disabled=running||!data.has_campaign;const resumable=data.resumable_campaign;if(resumable){$("continue-training").className="button primary";$("continue-training").textContent=`Continuar ${resumable.name} · rodada ${resumable.round} (${resumable.checkpoint})`}else{$("continue-training").className="button secondary";$("continue-training").textContent="Continuar de onde parou"}$("supervisor-restart").hidden=true;$("stop-training").disabled=!running;$("generate-report").disabled=!data.campaign_id;$("generate-report").title=data.campaign_id?"Gerar relatório desta campanha":"Nenhuma campanha selecionada";
if(!running&&stopping){if(data.last_completion?.safe){setMessage("Parado com segurança. Os saves foram restaurados.");stopping=false}else if(data.last_completion){setMessage("O treino parou, mas a checagem de restauração dos saves precisa de atenção.",true);stopping=false}}
const advanced=$("advanced-info");const details=[["IDs do lançamento",active.map(a=>a.launch_id).join(", ")||"—"],["Versão da pontuação",data.reward_version||"—"],["Caminho dos artefatos",data.advanced?.artifact_path||"—"],["Pasta compartilhada",data.advanced?.shared_root||"—"],["CPU lógica",navigator.hardwareConcurrency||"—"]];advanced.innerHTML=details.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join("");const focus=active.find(a=>a.role==="actor")||active[0];if(focus?.launch_id){pollLog(focus.launch_id)}else{$("raw-log").textContent="Nenhum processo ativo."}}
async function refresh(){try{const data=await api("/api/operator");render(data);renderHelpRequests(data.help_requests||[],data.help_request_history||[],data.campaign_id);$("supervisor-restart").hidden=true}catch(error){latestError=error;$("live-label").textContent=error.message;$("live-dot").className="dot error";const down=error.message.includes("O supervisor do treino não está rodando");$("supervisor-restart").hidden=!down;$("start-training").disabled=true;$("continue-training").disabled=true;$("repeat-training").disabled=true;setStatusBanner("error",down?"O supervisor do treino não está rodando.":"O painel não conseguiu atualizar o estado do treino.",error.message)}}
async function pollLog(id){if(id!==logLaunchId){logLaunchId=id;logOffset=0;$("raw-log").textContent=""}try{const data=await api(`/api/log?launch_id=${encodeURIComponent(id)}&offset=${logOffset}`);logOffset=data.next_offset;if(data.text){$("raw-log").textContent+=data.text;if($("raw-log").textContent.length>25000)$("raw-log").textContent=$("raw-log").textContent.slice(-25000)}}catch(_){}}
async function start(){const count=Number($("instance-count").value),kind=$("duration-kind").value;let value=null;if(kind==="hours")value=Number($("duration-hours").value);if(kind==="until_time")value=$("end-time").value;if(kind==="until_time"&&!value){setMessage("Escolha o horário para encerrar.",true);return}if(kind==="hours"&&(!Number.isFinite(value)||value<.25||value>72)){setMessage("Escolha entre 0,25 e 72 horas.",true);return}const saved=latest?.resumable_campaign;const confirmText=saved?`A campanha ${saved.name} continua guardada na rodada ${saved.round} (${saved.checkpoint}). Começar uma campanha nova vai abrir ${count} janela(s) do Hollow Knight. Feche seu jogo pessoal antes de continuar. Quer começar?`:`O treino vai abrir ${count} janela(s) do Hollow Knight. Feche o seu jogo pessoal antes de continuar. Quer começar uma campanha nova?`;if(!window.confirm(confirmText))return;setMessage("Preparando o treino e as cópias isoladas dos saves…");try{const result=await api("/api/operator/start",{method:"POST",body:JSON.stringify({instances:count,duration_kind:kind,duration_value:value,campaign_name:"jogada-1",help_stuck_count:Number($("help-stuck-count").value),help_stuck_minutes:Number($("help-stuck-minutes").value)})});setMessage(result.notice||"Treino iniciado. As janelas estão sendo preparadas.");await refresh()}catch(error){setMessage(error.message,true);setStatusBanner("error",`Não foi possível iniciar o treino: ${error.message}`,error.message)}}
async function launchAction(path,prompt){if(!window.confirm(prompt))return;setMessage("Preparando a próxima execução…");try{const result=await api(path,{method:"POST",body:JSON.stringify(path.endsWith("/continue")?{help_stuck_count:Number($("help-stuck-count").value),help_stuck_minutes:Number($("help-stuck-minutes").value)}:{})});setMessage(result.notice||"Execução iniciada.");await refresh()}catch(error){setMessage(error.message,true);setStatusBanner("error",`Não foi possível iniciar a execução: ${error.message}`,error.message)}}
async function playthroughAction(action,slot){if(!latest?.campaign_id)return;const isNew=action==="new",prompt=isNew?`Começar uma jogada nova na instância ${slot}? A jogada atual será arquivada e o save de referência será copiado uma única vez.`:`Restaurar o último backup bom na instância ${slot}? O jogo precisa estar parado.`;if(!window.confirm(prompt))return;setMessage(isNew?"Arquivando a jogada anterior e preparando a nova…":"Validando e restaurando o último backup…");try{await api(isNew?"/api/playthrough/new":"/api/playthrough/restore",{method:"POST",body:JSON.stringify({campaign_id:latest.campaign_id,slot:Number(slot)})});setMessage(isNew?"Nova jogada preparada.":"Backup restaurado na instância.");await refresh()}catch(error){setMessage(error.message,true)}}
async function stopSafely(){if(!window.confirm("Solicitar parada cooperativa? O treino termina o passo seguro, salva o checkpoint e restaura os saves isolados."))return;stopping=true;$("stop-training").disabled=true;setMessage("Parando com segurança: aguardando o ponto seguro e a restauração dos saves…");try{await api("/api/operator/stop",{method:"POST",body:"{}"});const deadline=Date.now()+30*60*1000;while(Date.now()<deadline){await new Promise(resolve=>setTimeout(resolve,2000));await refresh();if(latest?.status?.active_count===0&&latest?.last_completion?.safe){setMessage("Parado com segurança ✓ Os saves foram restaurados.");stopping=false;return}}setMessage("A parada continua em andamento. Esta tela seguirá acompanhando.");}catch(error){stopping=false;setMessage(error.message,true);await refresh()}}
async function generateReport(){if(!latest?.campaign_id)return;try{const report=await api("/api/reports/generate",{method:"POST",body:JSON.stringify({campaign_id:latest.campaign_id})});setMessage("Relatório gerado.");await refresh();window.open(`/api/report?path=${encodeURIComponent(report.html)}`,"_blank","noopener")}catch(error){setMessage(error.message,true)}}
$("duration-kind").addEventListener("change",()=>{$("hours-wrap").hidden=$("duration-kind").value!=="hours";$("time-wrap").hidden=$("duration-kind").value!=="until_time"});$("start-training").addEventListener("click",start);$("continue-training").addEventListener("click",()=>{const c=latest?.resumable_campaign;const prompt=c?`Continuar ${c.name} da rodada ${c.round}, checkpoint ${c.checkpoint}? O treino abrirá as janelas configuradas.`:"Continuar do último checkpoint da IA? O treino abrirá as janelas configuradas.";launchAction("/api/operator/continue",prompt)});$("repeat-training").addEventListener("click",()=>launchAction("/api/operator/repeat","Criar uma campanha nova do zero, com uma nova semente, e abrir as janelas do jogo?"));$("stop-training").addEventListener("click",stopSafely);$("generate-report").addEventListener("click",generateReport);$("refresh").addEventListener("click",refresh);$("supervisor-restart").addEventListener("click",async()=>{const button=$("supervisor-restart");button.disabled=true;try{await api("/api/operator/supervisor/restart",{method:"POST",body:"{}"});setMessage("Supervisor religado. Atualizando o painel…");await refresh()}catch(error){setStatusBanner("error","Não foi possível religar o supervisor.",error.message)}finally{button.disabled=false}});
$("playthrough-list").addEventListener("click",event=>{const button=event.target.closest("button[data-playthrough-action]");if(button)playthroughAction(button.dataset.playthroughAction,button.dataset.slot)});
$("challenge-list").addEventListener("click",async event=>{const button=event.target.closest("button[data-challenge-id]");if(!button||!latest?.campaign_id||latest.challenge_practice_enabled!==true)return;const challenge=button.dataset.challengeId,slot=Number(button.dataset.challengeSlot);if(!window.confirm(`Usar outro ator para treinar contra ${challenge} a partir de uma cópia isolada? A jogada principal continuará no outro ator.`))return;button.disabled=true;setMessage(`Carregando snapshot isolado de ${challenge}…`);try{await api("/api/challenges/practice",{method:"POST",body:JSON.stringify({campaign_id:latest.campaign_id,slot,challenge_id:challenge})});setMessage(`Ator de prática iniciado contra ${challenge}; rollouts seguem para o learner compartilhado.`);await refresh()}catch(error){setMessage(error.message,true);button.disabled=false}});
$("help-request-list").addEventListener("click",async event=>{const button=event.target.closest("button[data-help-action]");if(!button||!latest?.campaign_id)return;button.disabled=true;try{const result=await api("/api/help-requests/resolve",{method:"POST",body:JSON.stringify({campaign_id:latest.campaign_id,request_id:button.dataset.helpId,action:button.dataset.helpAction})});setMessage(result.status==="demonstration_requested"?"Demonstração autorizada; o pedido continua aberto até ser resolvido.":result.snoozed_until_unix?"Aviso adiado por 30 minutos; o pedido continua aberto.":"Pedido atualizado.");await refresh()}catch(error){setMessage(error.message,true);button.disabled=false}});
(async()=>{try{token=(await api("/api/session")).csrf_token;await refresh();setInterval(refresh,2500);setTimeout(()=>{if(!latest&&!latestError)setStatusBanner("warning","A resposta inicial do supervisor está demorando. A página continuará tentando atualizar.")},15000)}catch(error){latestError=error;$("live-label").textContent=error.message;$("live-dot").className="dot error";latestError=error;const down=error.message.includes("O supervisor do treino não está rodando");$("supervisor-restart").hidden=!down;setStatusBanner("error",down?"O supervisor do treino não está rodando.":"Não foi possível conectar ao painel.",error.message)}})();
