function renderChallenges(playthroughs,helpEnabled=false,practiceEnabled=false){const rows=(playthroughs||[]).flatMap(run=>(run.challenge_memory||[]).map(item=>({...item,slot:run.slot,snapshots:run.challenge_snapshots||[]})));const root=$("challenge-list");root.innerHTML=rows.length?rows.map(item=>{const failed=Math.max(0,(Number(item.attempts)||0)-(Number(item.wins)||0)),ask=helpEnabled&&failed>=100?`<strong class="alert">A IA pede ajuda: ${esc(item.challenge_id)} após ${failed} tentativas sem vencer. Pode mostrar como você faz?</strong>`:"",snapshot=item.snapshots.some(row=>row.challenge_id===item.challenge_id),button=practiceEnabled&&snapshot?`<button class="button secondary" data-challenge-id="${esc(item.challenge_id)}" data-challenge-slot="${esc(item.slot)}" ${item.slot==null?"disabled":""}>Treinar contra ${esc(item.challenge_id)}</button>`:"";return `<div class="scene-row"><div><strong>${esc(item.challenge_id)}</strong><span>${esc(item.kind||"desafio")} · ${Number(item.attempts)||0} tentativas · ${Number(item.wins)||0} vitórias · melhor progresso ${Number(item.best_progress)||0} · melhor sobrevivência ${fixed(Number(item.best_survival_seconds)||0,0)} s</span>${ask}<div class="button-row">${button}</div></div></div>`}).join(""):'<p class="empty">Ainda sem desafios registrados.</p>'}
function renderHelpRequests(pending,history,campaignId){const root=$("help-request-list"),received=$("help-history-list"),now=Date.now()/1000;root.innerHTML=pending.length?pending.map(row=>{const snoozed=Number(row.snoozed_until_unix)>now,openMinutes=Math.max(0,Math.floor((now-Number(row.created_unix||now))/60)),state=row.status==="demonstration_requested"?"Demonstração solicitada":snoozed?`Adiado até ${new Date(Number(row.snoozed_until_unix)*1000).toLocaleTimeString()}`:"Aberto";return `<div class="scene-row help-request"><div><strong>${esc(row.message||`Instância ${Number(row.slot)+1} pede ajuda — ${row.scene}`)}</strong><span>${state} · ${openMinutes} min em aberto · ${Number(row.stuck_count)||0} travadas · ${esc(row.place||row.scene)}</span>${row.request_id&&campaignId?`<img class="help-thumbnail" src="/api/help-thumbnail?campaign_id=${encodeURIComponent(campaignId)}&request_id=${encodeURIComponent(row.request_id)}" alt="Miniatura do local" loading="lazy">`:""}<div class="button-row"><button class="button primary" data-help-action="show" data-help-id="${esc(row.request_id)}" ${snoozed?"disabled":""}>Mostrar como faz</button>${row.status==="demonstration_requested"?`<button class="button primary" data-help-action="complete" data-help-id="${esc(row.request_id)}">Marcar ajuda concluída</button>`:`<button class="button secondary" data-help-action="now_not" data-help-id="${esc(row.request_id)}" ${snoozed?"disabled":""}>Agora não · 30 min</button>`}</div></div></div>`}).join(""):'<p class="empty">Nenhum pedido de ajuda aberto.</p>';const openIds=new Set(pending.map(row=>row.request_id)),rows=history.filter(row=>!openIds.has(row.request_id)&&row.status!=="pending").slice(-20).reverse(),labels={resolved_solo:"Resolvido por ela",resolved_with_help:"Resolvido com ajuda",completed:"Ajuda concluída",dismissed:"Dispensado",discarded:"Descartado"};received.innerHTML=rows.length?rows.map(row=>{const end=Number(row.resolved_unix||row.updated_unix||row.created_unix),minutes=Math.max(0,Math.floor((end-Number(row.created_unix||end))/60));return `<div class="scene-row"><div><strong>${esc(row.scene)} · ${esc(row.place)}</strong><span>${labels[row.status]||esc(row.status)} · ${Number(row.stuck_count)||0} travadas · ${minutes} min · ${new Date(Number(row.created_unix)*1000).toLocaleString()}</span></div></div>`}).join(""):'<p class="empty">Nenhuma ajuda resolvida ainda.</p>'}
function renderBestiary(playthroughs){const totals=new Map();for(const run of playthroughs||[])for(const item of run.bestiary||[]){const key=item.enemy_type_id;const row=totals.get(key)||{...item,encounters:0,wins:0,times_killed:0,damage_total:0,fought_total:0,geo_total:0,geo_count:0,hit_total:0,hit_count:0};row.encounters+=Number(item.encounters)||0;row.wins+=Number(item.wins)||0;row.times_killed+=Number(item.times_killed)||0;row.damage_total+=(Number(item.damage_per_encounter)||0)*(Number(item.encounters)||0);row.fought_total+=(Number(item.fight_rate)||0)*(Number(item.encounters)||0);if(item.average_geo!==null&&item.average_geo!==undefined&&Number.isFinite(Number(item.average_geo))){row.geo_total+=Number(item.average_geo)*(Number(item.wins)||0);row.geo_count+=Number(item.wins)||0}if(item.average_hits_to_defeat!==null&&item.average_hits_to_defeat!==undefined&&Number.isFinite(Number(item.average_hits_to_defeat))){row.hit_total+=Number(item.average_hits_to_defeat)*(Number(item.wins)||0);row.hit_count+=Number(item.wins)||0}totals.set(key,row)}const rows=[...totals.values()].sort((a,b)=>b.encounters-a.encounters);const root=$("bestiary-list");root.innerHTML=rows.length?'<div class="table-scroll"><table class="bestiary-table"><thead><tr><th>Inimigo</th><th>Encontros</th><th>Vitórias</th><th>Golpes p/ vencer</th><th>Dano/encontro</th><th>Mortes</th><th>Geo médio</th><th>Combate</th></tr></thead><tbody>'+rows.map(row=>'<tr><th>'+esc(row.name)+'</th><td>'+row.encounters+'</td><td>'+(row.encounters?fixed(100*row.wins/row.encounters,0)+'%':'—')+'</td><td>'+(row.hit_count?fixed(row.hit_total/row.hit_count,1):'—')+'</td><td>'+fixed(row.encounters?row.damage_total/row.encounters:0,1)+'</td><td>'+row.times_killed+'</td><td>'+(row.geo_count?fixed(row.geo_total/row.geo_count,0):'—')+'</td><td>'+(row.encounters?fixed(100*row.fought_total/row.encounters,0)+'%':'—')+'</td></tr>').join('')+'</tbody></table></div>':'<p class="empty">Inimigos aparecem depois do primeiro encontro.</p>'}
$("calibration-download").addEventListener("click",()=>$("map-download").click());$("map-download").addEventListener("click",async()=>{try{await api("/api/journey/map/download",{method:"POST",body:"{}"});setMessage("Preparação do mapa iniciada no cache local.");await refresh()}catch(error){setMessage(error.message,true)}});
$("map-import").addEventListener("click",()=>$("map-file").click());
$("map-file").addEventListener("change",async event=>{const file=event.target.files?.[0];if(!file)return;if(file.type!=="image/png"){setMessage("Escolha um arquivo PNG.",true);return}$("map-download").disabled=true;$("map-art-status").textContent=`Importando ${file.name} para o cache local…`;try{const response=await fetch("/api/journey/map/import",{method:"POST",headers:{"Content-Type":"image/png","X-Control-Token":token},body:file});const data=await response.json();if(!response.ok)throw new Error(data.error||`HTTP ${response.status}`);setMessage("PNG em cache; geração das tiles iniciada.");await refresh()}catch(error){setMessage(error.message,true)}finally{$("map-download").disabled=false;event.target.value=""}});
$("map-view-toggle").addEventListener("click",()=>{mapView.mode=mapView.mode==="art"?"schematic":"art";$("journey-map").dataset.renderKey="";if(latest)renderJourney(latest.journey)});
$("journey-run").addEventListener("change",()=>{mapView.anchors=[];mapView.worldAnchors=[];mapView.previewTransform=null;if(latest)renderJourney(latest.journey)});
function addWorldAnchor(x,y,label){if(!Number.isFinite(x)||!Number.isFinite(y)){setMessage("Não há referência de mundo válida para esse ponto.",true);return}const index=mapView.anchors.length;mapView.worldAnchors.push({x,y,label});mapView.anchors.push(null);mapView.activeAnchor=index;renderWizardPointList()}function selectedCapture(){const run=calibrationRun(),points=(run?.calibration_points||[]).filter(p=>p.scene===calibrationScene&&p.capture);return points[Number($("calibration-capture").value)||0]}function sceneBounds(){const run=calibrationRun(),positions=(run?.positions||[]).filter(p=>p.scene===calibrationScene&&Array.isArray(p.scene_bounds)&&p.scene_bounds.length===4);return positions.at(-1)?.scene_bounds}
$("calibration-scene").addEventListener("change",()=>{calibrationScene=$("calibration-scene").value;mapView.anchors=[];mapView.worldAnchors=[];mapView.previewTransform=null;if(latest)renderJourney(latest.journey)});$("calibration-capture").addEventListener("change",()=>renderCalibration(latest?.journey||{},latest?.journey?.map_art||{}));$("calibration-add-capture").addEventListener("click",()=>{const p=selectedCapture();if(p)addWorldAnchor(Number(p.x),Number(p.y),p.kind)});$("calibration-bound-left").addEventListener("click",()=>{const b=sceneBounds();if(b)addWorldAnchor(Number(b[0]),(Number(b[1])+Number(b[3]))/2,"left")});$("calibration-bound-right").addEventListener("click",()=>{const b=sceneBounds();if(b)addWorldAnchor(Number(b[2]),(Number(b[1])+Number(b[3]))/2,"right")});document.querySelectorAll('input[name="calibration-mode"]').forEach(input=>input.addEventListener("change",()=>{const bounds=input.value==="bounds"&&input.checked;$("calibration-bounds-controls").hidden=!bounds;$("calibration-capture-controls").hidden=bounds;mapView.anchors=[];mapView.worldAnchors=[];mapView.previewTransform=null;renderWizardPointList()}));$("calibration-save").addEventListener("click",async()=>{const fit=fitWizardTransform();if(!fit)return;const mode=document.querySelector('input[name="calibration-mode"]:checked')?.value||"bounds",anchors=mapView.worldAnchors.map((w,i)=>({world_x:w.x,world_y:w.y,map_x:mapView.anchors[i].x,map_y:mapView.anchors[i].y}));try{const result=await api("/api/journey/map/calibration",{method:"POST",body:JSON.stringify({campaign_id:latest.campaign_id,scene:calibrationScene,mode,anchors})});mapView.anchors=[];mapView.worldAnchors=[];mapView.previewTransform=null;setMessage(`Calibração salva para ${friendlyScene(calibrationScene)}. Salas posicionadas pelas passagens: ${(result.propagated_scenes||[]).filter(scene=>scene!==calibrationScene).map(friendlyScene).join(", ")||"nenhuma outra"}.`);await refresh()}catch(error){setMessage(error.message,true)}});$("calibration-remove").addEventListener("click",async()=>{try{await api("/api/journey/map/calibration/remove",{method:"POST",body:JSON.stringify({scene:calibrationScene})});mapView.anchors=[];mapView.worldAnchors=[];mapView.previewTransform=null;setMessage(`Calibração removida de ${friendlyScene(calibrationScene)}.`);await refresh()}catch(error){setMessage(error.message,true)}});$("calibration-undo").addEventListener("click",()=>{mapView.anchors.pop();mapView.worldAnchors.pop();mapView.activeAnchor=-1;renderWizardPointList()});$("calibration-redo").addEventListener("click",()=>{mapView.anchors=[];mapView.worldAnchors=[];mapView.activeAnchor=-1;mapView.previewTransform=null;renderWizardPointList()});$("calibration-open").addEventListener("click",()=>{const wizard=$("calibration-wizard");wizard.hidden=false;const canvas=$("map-canvas");if(canvas)$("calibration-map-slot").replaceChildren(canvas);if(!latest?.journey?.map_art?.tiles_ready){$("calibration-map-slot").innerHTML='<p class="empty">A arte ainda não está pronta. Feche o assistente e use “Baixar mapa e gerar tiles”.</p>'}else if(mapView.mode!=="art"){$("calibration-map-slot").innerHTML='<p class="empty">Selecione “Ver arte” no mapa para calibrar sobre a arte.</p>'}else if(latest)drawArtMap($("map-canvas"),latest.journey.map_art,latest.journey,calibrationRun());});$("calibration-close").addEventListener("click",()=>{const canvas=$("map-canvas");if(canvas)$("journey-map").replaceChildren(canvas);$("calibration-wizard").hidden=true});
function renderActorPerformance(rows){const root=$("actor-performance");root.innerHTML=rows.length?rows.map(row=>{const p=row.step_profile_ms||{},parts=[["política",p.policy_forward_ms],["env total",p.env_step_ms],["bridge aplicar",p.bridge_apply_rtt_ms],["bridge capturar",p.bridge_capture_rtt_ms],["decode",p.bridge_decode_ms],["conhecimento",p.task_player_knowledge_ms],["gravar conhecimento",p.task_player_knowledge_write_ms],["diário",p.task_diary_write_ms],["recompensa/log",p.task_reward_and_log_ms],["observação",p.task_knowledge_observation_ms],["buffer",p.buffer_ms]];const details=parts.filter(([,value])=>Number.isFinite(Number(value))).map(([name,value])=>`${name} ${fixed(value,1)} ms`).join(" · ");return `<article class="playthrough-row"><div><strong>Instância ${esc(row.slot)} · ${fixed(row.steps_per_second,2)} passos/s</strong><small>Coleta ${fixed(Number(row.collect_ms)/1000,1)} s por lote · ${esc(details||"perfil indisponível")}</small></div></article>`}).join(""):'<p class="empty">A medição detalhada aparece após a próxima coleta.</p>'}
